// Ported from the Node app's Sequelize model Vehicle (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class VehicleConfiguration : IEntityTypeConfiguration<Vehicle>
{
    public void Configure(EntityTypeBuilder<Vehicle> builder)
    {
        builder.ToTable("vehicles", t =>
        {
            t.HasCheckConstraint("CK_vehicles_status", "[status] IN (N'active', N'inactive')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.RegNo).HasColumnName("reg_no").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.Model).HasColumnName("model").HasColumnType("nvarchar(80)").HasMaxLength(80);
        builder.Property(e => e.Capacity).HasColumnName("capacity");
        builder.Property(e => e.InsuranceExpiry).HasColumnName("insurance_expiry").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'active'");
        builder.HasIndex(e => e.RegNo).IsUnique();
    }
}
